/* global document, Office, Word */

Office.onReady((info) => {
  if (info.host === Office.HostType.Word) {
    document.getElementById("btn-insert").onclick = insertAlgo;
    document.getElementById("btn-update").onclick = updateAlgo;

    Office.context.document.addHandlerAsync(
      Office.EventType.DocumentSelectionChanged,
      onSelectionChanged
    );
  }
});

function generateHtml(title, rawCode, fontFam, fontSize, lineHeightMult, lineColor) {
  const lines = rawCode.split('\n');
  let tableRowsHtml = '';
  let lineNumber = 1;
  const keywords = ['for', 'to', 'do', 'if', 'then', 'end', 'else if', 'else', 'while', 'return', 'in'];

  // 核心修复 1：将相对倍数行距换算为绝对磅数 (pt)，并强行接管 Word 排版
  const exactLineHeightPt = parseFloat(fontSize) * parseFloat(lineHeightMult);
  const baseStyle = `margin: 0 !important; padding: 0 !important; line-height: ${exactLineHeightPt}pt !important; mso-line-height-rule: exactly; font-family: '${fontFam}', serif; font-size: ${fontSize}pt;`;

  lines.forEach(line => {
    const indentMatch = line.match(/^[\s\t]+/);
    let spaceStr = indentMatch ? indentMatch[0] : '';
    let spaceCount = 0;
    for(let i=0; i<spaceStr.length; i++) {
      if(spaceStr[i] === '\t') spaceCount += 4;
      else spaceCount += 1;
    }
    const depth = Math.floor(spaceCount / 2);

    // 核心修复 2：竖线缝隙消除。将竖线的字号放大到与绝对行高相同，强行上下拼接。
    let indentPrefix = '';
    for(let i=0; i<depth; i++) {
      indentPrefix += `<span style="color: ${lineColor}; font-family: 'Consolas', monospace; font-size: ${exactLineHeightPt}pt; line-height: ${exactLineHeightPt}pt; vertical-align: middle; font-weight: normal; margin-right: 4px;">│</span>`;
    }

    let text = line.trim();
    if (text === '') return;

    text = text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    text = text.replace(/&lt;-/g, '&larr;');

    text = text.replace(/\b([A-Z][a-zA-Z0-9]*)\b/g, (match) => {
      const exclusions = ['Input', 'Output', 'Score', 'Require', 'Ensure', 'Algorithm'];
      if (exclusions.includes(match)) return match;
      return `<i style="font-family: '${fontFam}', serif;">${match}</i>`;
    });

    keywords.forEach(kw => {
      const regex = new RegExp(`\\b${kw}\\b`, 'g');
      text = text.replace(regex, `<strong style="font-style: normal;">${kw}</strong>`);
    });

    text = text.replace(/^(Input:|Output:|Require:|Ensure:)/, '<strong>$1</strong>');
    const isHeaderLine = text.startsWith("<strong>Input</strong>:") || text.startsWith("<strong>Output</strong>:") || text.startsWith("<i>Score</i>:");

    if (isHeaderLine) {
      tableRowsHtml += `<tr><td style="width: 25px; padding: 0;"><p style="${baseStyle}"></p></td><td style="padding: 0;"><p style="${baseStyle}">${indentPrefix}${text}</p></td></tr>`;
    } else {
      tableRowsHtml += `<tr>
        <td style="width: 25px; text-align: right; padding: 0 6px 0 0; vertical-align: top;">
          <p style="${baseStyle}"><strong>${lineNumber++}</strong></p>
        </td>
        <td style="padding: 0; vertical-align: top;">
          <p style="${baseStyle}">${indentPrefix}${text}</p>
        </td>
      </tr>`;
    }
  });

  return `
    <table style="width: 100%; border-collapse: collapse; border-top: 1.5pt solid black; border-bottom: 1.5pt solid black; margin-top: 8pt; margin-bottom: 8pt;">
      <tr>
        <td colspan="2" style="border-bottom: 1pt solid black; padding: 4px 0;">
          <p style="${baseStyle}"><strong>${title}</strong></p>
        </td>
      </tr>
      ${tableRowsHtml}
    </table>
  `;
}

// 收集 UI 数据，插入代码块
async function insertAlgo() {
  await Word.run(async (context) => {
    const title = document.getElementById("algoTitle").value;
    const rawCode = document.getElementById("algoCode").value;
    const fontFam = document.getElementById("uiFont").value;
    const fontSize = document.getElementById("uiSize").value;
    const lineHeight = document.getElementById("uiLineHeight").value;
    const lineColor = document.getElementById("uiLineColor").value;

    const htmlString = generateHtml(title, rawCode, fontFam, fontSize, lineHeight, lineColor);
    
    // 把颜色和行距等设置打包进数据，这样点击旧块时能完全恢复当时的设置
    const savedData = encodeURIComponent(JSON.stringify({ 
      title, code: rawCode, fontFam, fontSize, lineHeight, lineColor 
    }));

    const selection = context.document.getSelection();
    const cc = selection.insertContentControl();
    cc.title = "Algo_Block"; 
    cc.tag = savedData;      
    cc.appearance = "BoundingBox"; 
    cc.insertHtml(htmlString, "Replace");

    await context.sync();
  }).catch(err => document.getElementById("status").innerText = "插入失败: " + err);
}

// 更新代码块
async function updateAlgo() {
  await Word.run(async (context) => {
    const title = document.getElementById("algoTitle").value;
    const rawCode = document.getElementById("algoCode").value;
    const fontFam = document.getElementById("uiFont").value;
    const fontSize = document.getElementById("uiSize").value;
    const lineHeight = document.getElementById("uiLineHeight").value;
    const lineColor = document.getElementById("uiLineColor").value;

    const htmlString = generateHtml(title, rawCode, fontFam, fontSize, lineHeight, lineColor);
    const savedData = encodeURIComponent(JSON.stringify({ 
      title, code: rawCode, fontFam, fontSize, lineHeight, lineColor 
    }));

    const cc = context.document.getSelection().parentContentControlOrNullObject;
    cc.load("title");
    await context.sync();

    if (!cc.isNullObject && cc.title === "Algo_Block") {
      cc.tag = savedData; 
      cc.insertHtml(htmlString, "Replace"); 
      
      document.getElementById("status").innerText = "更新成功！";
      setTimeout(() => document.getElementById("status").innerText = "", 2000);
      await context.sync();
    }
  });
}

// 监听光标移动，恢复所有 UI 状态
async function onSelectionChanged() {
  await Word.run(async (context) => {
    let cc = context.document.getSelection().parentContentControlOrNullObject;
    cc.load(["title", "tag"]);
    await context.sync();

    const btnInsert = document.getElementById("btn-insert");
    const btnUpdate = document.getElementById("btn-update");
    const statusMsg = document.getElementById("status");

    if (!cc.isNullObject && cc.title === "Algo_Block") {
      try {
        const data = JSON.parse(decodeURIComponent(cc.tag));
        document.getElementById("algoTitle").value = data.title || "";
        document.getElementById("algoCode").value = data.code || "";
        if(data.fontFam) document.getElementById("uiFont").value = data.fontFam;
        if(data.fontSize) document.getElementById("uiSize").value = data.fontSize;
        if(data.lineHeight) document.getElementById("uiLineHeight").value = data.lineHeight;
        if(data.lineColor) document.getElementById("uiLineColor").value = data.lineColor;
        
        btnInsert.style.display = "none";
        btnUpdate.style.display = "block";
        statusMsg.innerText = "正在编辑代码块...";
        statusMsg.style.color = "#107c10";
      } catch(e) {}
    } else {
      btnInsert.style.display = "block";
      btnUpdate.style.display = "none";
      statusMsg.innerText = "";
    }
  }).catch(err => {});
}